mapper.select:
/* BizHourMapper.getDaysOverlapCnt */
SELECT  COUNT(*)
FROM    TB_MS_STORE_BIZHOUR_DAYS
WHERE   HQ_OFFICE_CD    =   #{hqOfficeCd}
AND     STORE_CD        =   #{storeCd}
AND     DAY_FG          =   #{dayFg}

AND     START_TIME      <   #{endTime}
AND     END_TIME        >   #{startTime}


    AND SEQ NOT IN
    #{exSeq}


    AND SEQ != #{seq}

/* BizHourMapper.getDaysMaxSeq */
SELECT  NVL(MAX(SEQ), 0) + 1
FROM    TB_MS_STORE_BIZHOUR_DAYS
WHERE   HQ_OFFICE_CD    =   #{hqOfficeCd}
AND     STORE_CD        =   #{storeCd}
AND     DAY_FG          =   #{dayFg}

mapper.update:
/* BizHourMapper.updateDays */
UPDATE  TB_MS_STORE_BIZHOUR_DAYS
SET     START_TIME  = #{startTime},
        END_TIME    = #{endTime},
        MOD_DT      = #{modDt},
        MOD_ID      = #{modId}
WHERE   HQ_OFFICE_CD    = #{hqOfficeCd}
AND     STORE_CD        = #{storeCd}
AND     DAY_FG          = #{dayFg}
AND     SEQ             = #{seq}

mapper.delete:
/* BizHourMapper.deleteDays */
DELETE  TB_MS_STORE_BIZHOUR_DAYS
WHERE   HQ_OFFICE_CD    = #{hqOfficeCd}
AND     STORE_CD        = #{storeCd}
AND     DAY_FG          = #{dayFg}
AND     SEQ             = #{seq}

