SET     BIZ_FG      = #{bizFg},
        START_TIME  = #{startTime},
        END_TIME    = #{endTime},
        REMARK      = #{remark},
        MOD_DT      = #{modDt},
        MOD_ID      = #{modId}
WHERE   HQ_OFFICE_CD    = #{hqOfficeCd}
AND     STORE_CD        = #{storeCd}
AND     BIZ_DATE        = #{bizDate}
AND     SEQ             = #{seq}

